import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes — 2024","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-2024.md","filePath":"aireblock-releases/AireFrame/aireframe-2024.md","lastUpdated":1787058499000}`),a={name:`aireblock-releases/AireFrame/aireframe-2024.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes-—-2024" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes — 2024</span> <a class="header-anchor" href="#aireframe-release-notes-—-2024" aria-label="Permalink to “AireFrame Release Notes — 2024”">​</a></h1><p>This page contains the AireFrame releases published during 2024.</p><h2 id="version-2-24-0-—-visualisation-filters-liquid-support" tabindex="-1">Version 2.24.0 — Visualisation Filters Liquid Support <a class="header-anchor" href="#version-2-24-0-—-visualisation-filters-liquid-support" aria-label="Permalink to “Version 2.24.0 — Visualisation Filters Liquid Support”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 19, 2024</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for Liquid expressions in visualisation filters</li><li>Store who uploaded a PDF, with option to expose on a visualisation</li></ul><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Highlight current page in navigation panel when in the configuration section</li><li>CSP frame-sources are now restricted to the configured iframes of the tenant</li><li>Performance improvements</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where on-demand visualisation filters were not validated</li><li>Fix issue where boolean visualisation filter values could not be unchecked</li><li>Fix issue where time visualisation filters did not work</li><li>Fix issue where default date time visualisation filters were not rehydrated in the on-demand filter UI</li></ul><h2 id="version-2-23-0-—-aireflow-resource-restrictions-rest-api" tabindex="-1">Version 2.23.0 — AireFlow Resource Restrictions &amp; REST API <a class="header-anchor" href="#version-2-23-0-—-aireflow-resource-restrictions-rest-api" aria-label="Permalink to “Version 2.23.0 — AireFlow Resource Restrictions &amp; REST API”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 13, 2024</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for AireFlow task resource restrictions</li><li>Add update subject REST API</li><li>Allow select all structural entity children when creating groups</li><li>Add support for user identifiers in pie charts</li></ul><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Switch to per-tenant job queues</li><li>Improve git export error message</li></ul><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where display options were not being rehydrated into the visualisation designer</li><li>Fix Monaco autocompletion</li></ul><h2 id="version-2-22-0-—-portal-invite-api-autocompletion" tabindex="-1">Version 2.22.0 — Portal Invite API &amp; Autocompletion <a class="header-anchor" href="#version-2-22-0-—-portal-invite-api-autocompletion" aria-label="Permalink to “Version 2.22.0 — Portal Invite API &amp; Autocompletion”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 18, 2024</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add subject portal invite REST API</li></ul><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve Liquid Monaco autocompletion with nested objects</li><li>Improve bundled data source names</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where a group with key <code>new</code> could not be viewed/edited</li><li>Fix issue where showing a status icon on a widget with a long enough title would place it onto a new line</li><li>Fix issue where a visualisation with a default filter could not be imported</li></ul><h2 id="version-2-21-0-—-new-api-endpoints" tabindex="-1">Version 2.21.0 — New API Endpoints <a class="header-anchor" href="#version-2-21-0-—-new-api-endpoints" aria-label="Permalink to “Version 2.21.0 — New API Endpoints”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 12, 2024</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add get subjects API</li><li>Add get structural entity by key API</li><li>Add support for widget context in the HTML visualisation</li><li>Show an incoming update icon on widgets when there is new data that has not yet been processed</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Add back to list link on subject page</li></ul><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where subject invite link could be longer than the screen width</li><li>Fix issue where stale data icon was shown if the user had stayed on the page for more than 5 minutes</li><li>Fix issue where multiple choice options could be taken from the wrong field</li></ul><h2 id="version-2-20-0-—-structural-entity-custom-fields" tabindex="-1">Version 2.20.0 — Structural Entity Custom Fields <a class="header-anchor" href="#version-2-20-0-—-structural-entity-custom-fields" aria-label="Permalink to “Version 2.20.0 — Structural Entity Custom Fields”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 4, 2024</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add custom fields to structural entities based on the structure type</li><li>Add ability to reference contextual data via Liquid expressions in widgets</li><li>Add support for colouring charts by series values using a Liquid expression</li><li>Add resource restrictions for which forms a user can create</li><li>Add get subject by ID API</li><li>Add get structural entities API</li><li>Add update structural entity API</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where search results had blank lines</li><li>Fix issue where pagination would not work if sorting values were the same</li><li>Fix issue where cached data sets would not update if multiple updates were received in quick succession</li></ul><h2 id="version-2-19-0-—-structural-entity-events-chart-improvements" tabindex="-1">Version 2.19.0 — Structural Entity Events &amp; Chart Improvements <a class="header-anchor" href="#version-2-19-0-—-structural-entity-events-chart-improvements" aria-label="Permalink to “Version 2.19.0 — Structural Entity Events &amp; Chart Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 7, 2024</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Publish Structural Entity Events (Create, Update, Delete) to AireFlow</li><li>Add extra string filter comparators (Does not equal, Does not contain, Does not start with, Does not end with)</li><li>Expose extra pie chart options (Full pie/Donut, Show legend, Show labels)</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Hide subject preview action button if subject provider is read-only</li><li>Truncate long labels on bar charts</li></ul><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where data was not returned for sorted visualisations when a column contained a repeated value</li><li>Fix issue where a primary field could not be moved to a group</li><li>Fix issue where a filtered subject list did not show the data from all visualisations</li><li>Fix issue where form notification was not marked as read when it was auto-launched</li><li>Fix issue where the JWT token was not always refreshed when it expired</li><li>Fix issue where Liquid input values were always treated as strings</li></ul><h2 id="version-2-18-0-—-filtering-improvements" tabindex="-1">Version 2.18.0 — Filtering Improvements <a class="header-anchor" href="#version-2-18-0-—-filtering-improvements" aria-label="Permalink to “Version 2.18.0 — Filtering Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 17, 2024</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to define default filters for a visualisation</li><li>Add hidden series that can be filtered and sorted but not displayed</li><li>Dashboard filters, paging and active location are encoded in the URL, allowing direct linking</li><li>Add tenant-level multi-subject view</li><li>Add REST endpoint to look up users who can access a subject</li></ul><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved UI showing when a filter has been applied</li><li>Allow page size to be changed on all paged lists</li><li>No longer use pointer cursor when graph is not clickable</li></ul><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where location search would not auto-expand to matched results</li><li>Fix issue where AireForms amend events were not handled correctly</li><li>Fix issue where a failed subject search would not show an error message</li><li>Fix issue where filtering on an aggregated visualisation on the subject list would return no results</li></ul><h2 id="version-2-17-0-—-aireflow-task-assignment" tabindex="-1">Version 2.17.0 — AireFlow Task Assignment <a class="header-anchor" href="#version-2-17-0-—-aireflow-task-assignment" aria-label="Permalink to “Version 2.17.0 — AireFlow Task Assignment”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 2, 2024</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to assign AireFlow tasks to users from widget actions</li></ul><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Update search page to match the multi-subject list, including dashboards</li><li>Add loading spinner to iframe widgets before content is loaded</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where stale data warning would show if the page had not been refreshed</li></ul><h2 id="version-2-16-0-—-subject-list-filtering-sorting" tabindex="-1">Version 2.16.0 — Subject List Filtering &amp; Sorting <a class="header-anchor" href="#version-2-16-0-—-subject-list-filtering-sorting" aria-label="Permalink to “Version 2.16.0 — Subject List Filtering &amp; Sorting”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 14, 2024</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to filter and sort the subject list by any cache-able visualisation series</li><li>Support display of AireFlow assignee in table widgets</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where saving subject configuration failed if the name of a banner group was changed</li><li>Fix issue where section dashboard order was not retained</li></ul><h2 id="version-2-15-0-—-performance-improvements" tabindex="-1">Version 2.15.0 — Performance Improvements <a class="header-anchor" href="#version-2-15-0-—-performance-improvements" aria-label="Permalink to “Version 2.15.0 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 31, 2024</p></blockquote><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Introduce distributed locks to reduce load on downstream systems when populating caches</li><li>Support display of users in table widgets</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where visualisation cache was constantly being invalidated</li><li>Fix issue where multiple data points were shown per subject on the subjects list when the visualisation had a filter, aggregate and/or group by</li><li>Fix issue where subject avatar toggle was not transferred across environments</li></ul><h2 id="version-2-14-0-—-visualisation-filtering" tabindex="-1">Version 2.14.0 — Visualisation Filtering <a class="header-anchor" href="#version-2-14-0-—-visualisation-filtering" aria-label="Permalink to “Version 2.14.0 — Visualisation Filtering”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 25, 2024</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to filter visualisations by any defined series</li><li>Realtime AireFlow task updates on visualisations</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Migrate to AireAudit for audit logs</li><li>Improve user group assignment UI</li><li>Add border to subject avatar</li><li>Switch subject avatar fetching to use HTTP streaming instead of Base64</li><li>Centre align table headers on visualisations</li></ul><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where configuration was wiped when trying to edit a Liquid visualisation</li></ul><h2 id="version-2-13-0-—-default-group" tabindex="-1">Version 2.13.0 — Default Group <a class="header-anchor" href="#version-2-13-0-—-default-group" aria-label="Permalink to “Version 2.13.0 — Default Group”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 9, 2024</p></blockquote><h3 id="✨-new-features-10" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-10" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add default group that, when assigned to a user, allows access to all structural entities</li><li>Add ability to search groups</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where user name would sometimes come through as <code>Unknown</code></li></ul><h2 id="version-2-12-0-—-performance-improvements" tabindex="-1">Version 2.12.0 — Performance Improvements <a class="header-anchor" href="#version-2-12-0-—-performance-improvements" aria-label="Permalink to “Version 2.12.0 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 2, 2024</p></blockquote><h3 id="✨-new-features-11" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-11" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add REST API for clearing a data set cache programmatically</li><li>Add ability to drag and drop series in the WYSIWYG visualisation designer</li><li>Add ability to set text colour in the WYSIWYG visualisation designer</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Performance improvements to the structure tree</li><li>Add support for hyperlinks in sanitised HTML</li><li>Keep the search box visible when scrolling through the location tree</li><li>General improvements to the WYSIWYG visualisation designer</li></ul><h2 id="version-2-11-0-—-subject-avatar" tabindex="-1">Version 2.11.0 — Subject Avatar <a class="header-anchor" href="#version-2-11-0-—-subject-avatar" aria-label="Permalink to “Version 2.11.0 — Subject Avatar”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 11, 2024</p></blockquote><h3 id="✨-new-features-12" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-12" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add subject avatar to the subject banner</li><li>Add ability to withdraw an uploaded PDF document</li></ul><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Add delete confirmation before deleting a dashboard</li><li>Add hover background colour to table rows</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where static assets were not being cached</li><li>Fix issue where page counter was incorrect when a filter was changed</li><li>Fix issue where data set errors on the subject list were repeated</li><li>Fix issue where the user name was sometimes shown as <code>Unknown</code> in the navbar</li></ul><h2 id="version-2-10-0-—-wysiwyg-html-visualisations" tabindex="-1">Version 2.10.0 — WYSIWYG HTML Visualisations <a class="header-anchor" href="#version-2-10-0-—-wysiwyg-html-visualisations" aria-label="Permalink to “Version 2.10.0 — WYSIWYG HTML Visualisations”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 21, 2024</p></blockquote><h3 id="✨-new-features-13" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-13" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add a WYSIWYG visualisation type to allow custom formatting of an aggregated data point</li><li>Add MinBy and MaxBy aggregators to retrieve an entire data point by the lowest specified values</li><li>Add ability to drag custom fields from one group to another</li><li>Add a footer</li><li>Add copy button to custom fields for quick key copying</li></ul><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve git repository connection failure messaging</li><li>Add max height to available fields in visualisation designer to stop drag-scrolling</li></ul><h3 id="🐞-bug-fixes-13" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-13" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where updating a visualisation required a refresh before changes were visible</li><li>Fix issue with removing a custom field when using a read-only subject provider</li><li>Changing the subject provider now clears the inbound subject configuration</li><li>Changing the subject provider now clears user-group associations</li><li>Fix issue where the structure tree required a refresh after changing the parent of a structural entity</li></ul><h2 id="version-2-9-0-—-banner-groups-restricted-fields" tabindex="-1">Version 2.9.0 — Banner Groups &amp; Restricted Fields <a class="header-anchor" href="#version-2-9-0-—-banner-groups-restricted-fields" aria-label="Permalink to “Version 2.9.0 — Banner Groups &amp; Restricted Fields”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 7, 2024</p></blockquote><h3 id="✨-new-features-14" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-14" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to define groups of fields to display in the subject banner</li><li>Add ability to restrict fields based on policies defined in AireIdentity</li><li>Add search filter to visualisation available fields</li><li>Allow tenant to set a custom error message for the portal when the user is not linked to a subject</li><li>Add option to send the bearer token in the query parameter for an iframe</li></ul><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Collapse banner by default on the portal site</li><li>Order available configuration imports from newest to oldest</li><li>Subject edit and subject location forms are read-only for a read-only subject provider</li></ul><h3 id="🐞-bug-fixes-14" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-14" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix configuration import for read-only subject provider</li><li>Fix timeframe picker mandatory field validation</li><li>Fix count aggregate visualisation on multi-subject view</li><li>Fix location search spinning indefinitely</li><li>Fix search result pagination and alignment</li><li>Fix structure type creation</li><li>Fix linking an existing user to a subject clearing their groups</li><li>Fix multi-subject view error if access to the user&#39;s default location was revoked</li></ul><h2 id="version-2-8-0-—-external-structure-provider" tabindex="-1">Version 2.8.0 — External Structure Provider <a class="header-anchor" href="#version-2-8-0-—-external-structure-provider" aria-label="Permalink to “Version 2.8.0 — External Structure Provider”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 10, 2024</p></blockquote><h3 id="✨-new-features-15" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-15" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for fetching structure types, entities and groups from the subject provider</li><li>Add search model to location tree</li><li>Add subject invite link in UI after invite</li><li>Allow tenanted login using <code>https://[tenant].frame.aireinnovate.com</code></li><li>Display tenant environment name in the UI</li><li>Support read-only subject providers</li><li>Add subject created/updated event notifications</li></ul><h3 id="⚡-improvements-13" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-13" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Tenant display name is retrieved from the token rather than stored in the database</li><li>Add logic to invalidate client credentials token on 401 response</li><li>Improve last selected location behaviour</li><li>Improve error message when creating a data source instance with an existing key</li></ul><h3 id="🐞-bug-fixes-15" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-15" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix user group list not updating after adding user to a group</li><li>Fix frontend visualisation data caching issue</li><li>Fix issue where creating a new dashboard would show an error</li><li>Fix widget search</li><li>Fix issue where widget delete modal did not close on delete</li></ul><h2 id="version-2-7-0-—-portal-site-single-step-onboarding" tabindex="-1">Version 2.7.0 — Portal Site &amp; Single Step Onboarding <a class="header-anchor" href="#version-2-7-0-—-portal-site-single-step-onboarding" aria-label="Permalink to “Version 2.7.0 — Portal Site &amp; Single Step Onboarding”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 10, 2024</p></blockquote><h3 id="✨-new-features-16" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-16" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Migrate permissions and roles to AireIdentity</li><li>Reflect user list from AireIdentity</li><li>Add read-only subject provider</li><li>Add separate portal widgets and dashboards</li><li>Add support for Forms4Health partial date control</li></ul><h3 id="⚡-improvements-14" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-14" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Export transfer configuration now uses notifications to handle large exports</li></ul><h2 id="version-2-6-0-—-authentication-ui-improvements" tabindex="-1">Version 2.6.0 — Authentication &amp; UI Improvements <a class="header-anchor" href="#version-2-6-0-—-authentication-ui-improvements" aria-label="Permalink to “Version 2.6.0 — Authentication &amp; UI Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 23, 2024</p></blockquote><h3 id="✨-new-features-17" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-17" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Replace OIDC with cookie authentication flows</li><li>Add search filter to user list</li><li>Add option to display headers in a table visualisation</li><li>Ability to create a dynamic series name</li><li>Add Forms data set author filter option</li></ul><h3 id="⚡-improvements-15" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-15" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve widget search filter</li><li>Split <code>edit:user</code> permission into <code>create:usergroup</code> and <code>delete:usergroup</code> for finer-grained control</li><li>Only render import/export tabs on configuration page if tenant has a repository configured</li><li>Dashboard selector is no longer displayed if there is only one dashboard</li></ul><h3 id="🐞-bug-fixes-16" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-16" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where filtered visualisation totals showed the pre-filtered total</li><li>Fix issue where structure type name could not be updated</li></ul><h2 id="version-2-5-0-—-visualisation-form-improvements" tabindex="-1">Version 2.5.0 — Visualisation &amp; Form Improvements <a class="header-anchor" href="#version-2-5-0-—-visualisation-form-improvements" aria-label="Permalink to “Version 2.5.0 — Visualisation &amp; Form Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 24, 2024</p></blockquote><h3 id="✨-new-features-18" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-18" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for <code>contains</code> operator in the visualisation pipeline</li><li>Forms are now grouped by classification in the add form modal</li><li>Add extra security checks to PDF upload</li></ul><h3 id="⚡-improvements-16" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-16" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Right-side overlay now opens full screen by default, with a button to shrink to 50%</li><li>Improve visualisation designer group-by selector for a large number of options</li></ul><h3 id="🐞-bug-fixes-17" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-17" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where grouped bar charts were not coloured correctly</li><li>Fix issue where the key of a widget could not be changed on creation if it was not unique</li></ul><h2 id="version-2-4-0-—-iframe-widgets" tabindex="-1">Version 2.4.0 — IFrame Widgets <a class="header-anchor" href="#version-2-4-0-—-iframe-widgets" aria-label="Permalink to “Version 2.4.0 — IFrame Widgets”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 10, 2024</p></blockquote><h3 id="✨-new-features-19" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-19" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>New iframe widget type that can be used to embed external content</li><li>Add ability to clear the cache for a data set</li></ul><h3 id="🔒-security" tabindex="-1">🔒 Security <a class="header-anchor" href="#🔒-security" aria-label="Permalink to “🔒 Security”">​</a></h3><ul><li>Add Strict-Transport-Security and Permissions-Policy headers</li></ul><h3 id="⚡-improvements-17" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-17" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve stale data message</li><li>Hide graph key for a categorical (aggregated) visualisation</li><li>Move menu item tooltips to the right</li><li>Centre align subject list elements</li><li>Improve widget layout</li></ul><h3 id="🐞-bug-fixes-18" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-18" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix incorrect data extract list permission check</li></ul>`,160)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};